'use strict';
const tg = window.Telegram && window.Telegram.WebApp;
if (tg) { try { tg.ready(); tg.expand(); } catch (e) {} }
const $app = document.getElementById('app');
const e = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const S = { me: null, route: { name: 'dashboard', p: {} }, stack: [], q: {}, sheets: 0 };
const ini = (n) => (String(n || '?').replace(/^(CA|Prof|Dr)\.?\s+/i, '').split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0].toUpperCase()).join('') || '?');
const fmtD = (t) => t ? new Date(t).toLocaleString([], { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
const fmtDay = (t) => t ? new Date(t).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' }) : '—';
const rid = () => Math.random().toString(36).slice(2) + Date.now().toString(36);
const can = (p) => !!S.me && (S.me.perms.includes('*') || S.me.perms.includes(p));
const ST = { active: 'green', upcoming: 'amber', completed: 'pri', archived: 'dim', inactive: 'dim', blocked: 'red' };
const pl = (n, w, p) => n + ' ' + (n === 1 ? w : (p || w + 's'));
const cap = (s) => String(s || '').charAt(0).toUpperCase() + String(s || '').slice(1);

/* ── API ─────────────────────────────────────────────── */
async function api(method, path, body) {
  const h = { 'Content-Type': 'application/json', 'x-tg-init-data': (tg && tg.initData) || '' };
  if (method !== 'GET') h['x-request-id'] = rid();
  let r; try { r = await fetch('/api/admin' + path, { method, headers: h, body: body ? JSON.stringify(body) : undefined }); } catch (x) { throw new Error('Network error'); }
  let j = {}; try { j = await r.json(); } catch (x) {}
  if (!r.ok || !j.success) { const err = new Error(j.error || 'Request failed (' + r.status + ')'); err.status = r.status; throw err; }
  return j.data;
}
const qs = (o) => { const p = new URLSearchParams(); Object.entries(o).forEach(([k, v]) => { if (v !== '' && v != null && v !== false) p.set(k, v); }); const s = p.toString(); return s ? '?' + s : ''; };

/* ── UI helpers ──────────────────────────────────────── */
function toast(msg, kind) { document.querySelectorAll('.toast').forEach((t) => t.remove()); const t = document.createElement('div'); t.className = 'toast ' + (kind || ''); t.innerHTML = '<i class="ti ti-' + (kind === 'err' ? 'alert-circle' : 'circle-check') + '"></i><span>' + e(msg) + '</span>'; $app.appendChild(t); setTimeout(() => t.remove(), 2800); }
const fail = (x) => toast(x.message || 'Something went wrong', 'err');
function sheet(html, { onClose } = {}) {
  const ov = document.createElement('div'); ov.className = 'ov'; ov.innerHTML = '<div class="sheet"><div class="grab"></div><button class="sx" data-sx aria-label="Close"><i class="ti ti-x"></i></button>' + html + '</div>';
  ov.addEventListener('click', (ev) => { if (ev.target === ov || ev.target.closest('[data-sx]')) close(); });
  function close() { ov.remove(); if (onClose) onClose(); } ov.close = close; $app.appendChild(ov); return ov;
}
function confirmBox(title, text, okLabel, danger) { return new Promise((res) => { const ov = sheet('<h3>' + e(title) + '</h3><div class="sub2">' + e(text) + '</div><div class="foot"><button class="btn ghost" data-r="0">Cancel</button><button class="btn ' + (danger ? 'rose' : '') + '" data-r="1">' + e(okLabel || 'Confirm') + '</button></div>'); ov.addEventListener('click', (ev) => { const b = ev.target.closest('[data-r]'); if (b) { ov.close(); res(b.dataset.r === '1'); } }); ov.addEventListener('click', (ev) => { if (ev.target === ov) res(false); }); }); }
/* Generic form sheet. fields: {k,label,type,options:[[v,l]],value,required,hint,max} */
function form({ title, sub, fields, submit, onSubmit, extra }) {
  const f = (x) => {
    const id = 'f_' + x.k, v = x.value == null ? '' : x.value, r = x.required ? ' *' : '';
    let c;
    if (x.type === 'textarea') c = '<textarea class="ta" id="' + id + '" maxlength="' + (x.max || 1000) + '">' + e(v) + '</textarea>';
    else if (x.type === 'select') c = '<select class="sel" id="' + id + '">' + (x.options || []).map(([ov, ol]) => '<option value="' + e(ov) + '"' + (String(ov) === String(v) ? ' selected' : '') + '>' + e(ol) + '</option>').join('') + '</select>';
    else if (x.type === 'check') return '<div class="fld"><label class="chk"><input type="checkbox" id="' + id + '"' + (v ? ' checked' : '') + '> <span>' + e(x.label) + '</span></label></div>';
    else if (x.type === 'multi') c = '<div class="msel" id="' + id + '">' + (x.options || []).map(([ov, ol]) => '<label><input type="checkbox" value="' + e(ov) + '"' + ((v || []).includes(ov) ? ' checked' : '') + '> ' + e(ol) + '</label>').join('') + '</div>';
    else c = '<input class="inp" id="' + id + '" type="' + (x.type || 'text') + '" value="' + e(v) + '" maxlength="' + (x.max || 200) + '" placeholder="' + e(x.ph || '') + '">';
    return '<div class="fld"><label>' + e(x.label) + r + '</label>' + c + (x.hint ? '<div class="hint">' + e(x.hint) + '</div>' : '') + '</div>';
  };
  const ov = sheet('<h3>' + e(title) + '</h3>' + (sub ? '<div class="sub2">' + e(sub) + '</div>' : '') + fields.map(f).join('') + (extra || '') + '<div class="foot"><button class="btn ghost" data-x="c">Cancel</button><button class="btn" data-x="s">' + e(submit || 'Save') + '</button></div>');
  ov.addEventListener('click', async (ev) => {
    const b = ev.target.closest('[data-x]'); if (!b) return; if (b.dataset.x === 'c') return ov.close();
    const vals = {};
    for (const x of fields) { const el = ov.querySelector('#f_' + x.k); if (x.type === 'check') vals[x.k] = el.checked; else if (x.type === 'multi') vals[x.k] = [...el.querySelectorAll('input:checked')].map((i) => i.value); else vals[x.k] = el.value; }
    b.disabled = true; try { await onSubmit(vals, ov); ov.close(); } catch (x) { fail(x); b.disabled = false; }
  });
  return ov;
}
const row = (o) => '<div class="rowc ' + (o.tone || '') + '" data-a="' + o.a + '" data-id="' + e(o.id) + '">' + (o.av || '') + '<div class="mid"><div class="nm">' + e(o.name) + '</div>' + (o.chips ? '<div class="chips">' + o.chips + '</div>' : '') + '</div><div class="chev"><i class="ti ti-chevron-right"></i></div></div>';
const chip = (t, c, i) => '<span class="chip ' + (c || '') + '">' + (i ? '<i class="ti ti-' + i + '"></i>' : '') + e(t) + '</span>';
const av = (name, pic, color) => '<div class="avc"' + (color ? ' style="background:linear-gradient(145deg,' + e(color) + ',#4b3fa8)"' : '') + '>' + (pic ? '<img src="' + e(pic) + '" alt="">' : e(ini(name))) + '</div>';
const sec = (t, right) => '<div class="sec">' + e(t) + '<span class="sp"></span>' + (right || '') + '</div>';
