const seg = (key, items, cur, cls) => '<div class="seg ' + (cls || '') + '">' + items.map(([v, l, ic]) => '<button class="' + (v === cur ? 'on' : '') + '" data-a="seg" data-k="' + key + '" data-v="' + e(v) + '">' + (ic ? '<i class="ti ti-' + ic + '"></i>' : '') + e(l) + '</button>').join('') + '</div>';
