function download(name, text, mime) { try { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([text], { type: mime || 'text/plain' })); a.download = name; document.body.appendChild(a); a.click(); a.remove(); toast('Download started', 'ok'); } catch (x) { fail(new Error('Download not supported here')); } }

/* ── Router ──────────────────────────────────────────── */
const ROOTS = [['dashboard', 'Home', 'smart-home'], ['students', 'Students', 'users'], ['batches', 'Batches', 'books'], ['faculties', 'Faculty', 'school'], ['more', 'More', 'layout-grid']];
function go(name, p) { S.stack.push(S.route); S.route = { name, p: p || {} }; draw(); }
function root(name) { S.stack = []; S.route = { name, p: {} }; draw(); }
function back() { S.route = S.stack.pop() || { name: 'dashboard', p: {} }; draw(); }
let drawing = 0;
async function draw() {
  clearInterval(window._lt); const my = ++drawing; const main = document.getElementById('main'); if (!main) return;
  const rootName = ['students', 'student', 'batches', 'batch', 'faculties', 'faculty', 'dashboard'].includes(S.route.name) ? ({ student: 'students', batch: 'batches', faculty: 'faculties' }[S.route.name] || S.route.name) : 'more';
  document.querySelectorAll('.nav button').forEach((b) => b.classList.toggle('on', b.dataset.id === rootName));
  main.innerHTML = skl;
  try { const html = await V[S.route.name](S.route.p); if (my !== drawing) return; main.innerHTML = html; main.scrollTop = 0; const post = P[S.route.name]; if (post) await post(S.route.p); }
  catch (x) { if (my !== drawing) return; main.innerHTML = empty('alert-triangle', x.message || 'Failed to load') + '<div style="text-align:center"><button class="btn sm" data-a="reload">Retry</button></div>'; }
}
const refresh = () => draw();
