const V = {}, P = {}, A = {};
async function fillList(id, path, params, render, emptyMsg, icon) {
  const box = document.getElementById(id); if (!box) return;
  const page = params.page || 1; let d;
  try { d = await api('GET', path + qs(params)); } catch (x) { box.innerHTML = empty('alert-triangle', x.message); return; }
  if (!document.getElementById(id)) return;
  const html = d.items.map(render).join('');
  if (page === 1) box.innerHTML = d.items.length ? html : empty(icon || 'inbox', emptyMsg || 'Nothing here yet'); else box.insertAdjacentHTML('beforeend', html);
  box.querySelectorAll('.more-btn').forEach((b) => b.parentElement.remove());
  if (d.page < d.pages) box.insertAdjacentHTML('beforeend', '<div style="text-align:center"><button class="btn ghost sm more-btn" data-a="more" data-list="' + id + '">Load more (' + (d.total - d.page * d.size) + ' left)</button></div>');
  box._ctx = { path, params: { ...params }, render, emptyMsg, icon }; return d;
}
