function imgToDataUri(file, size = 256) { return new Promise((res, rej) => { if (!/^image\//.test(file.type)) return rej(new Error('Choose an image file')); const im = new Image(); const u = URL.createObjectURL(file); im.onload = () => { const c = document.createElement('canvas'); c.width = c.height = size; const x = c.getContext('2d'), s = Math.min(im.width, im.height); x.drawImage(im, (im.width - s) / 2, (im.height - s) / 2, s, s, 0, 0, size, size); URL.revokeObjectURL(u); res(c.toDataURL('image/jpeg', 0.82)); }; im.onerror = () => rej(new Error('Could not read image')); im.src = u; }); }
/** Ask the server for a one-time bot link, then show it with an Open button. */
async function botLink(path, title, hint) { let r; try { r = await api('POST', path, {}); } catch (x) { return toast(x.message, 'err'); } if (!r.url) return toast('Bot username is not known yet — restart the server with the bot token set.', 'err');
  try { if (window.Telegram && Telegram.WebApp && Telegram.WebApp.openTelegramLink) return Telegram.WebApp.openTelegramLink(r.url); } catch (x) {} window.open(r.url, '_blank'); toast(title + ': ' + hint, 'ok'); }
const runThen = (fn, msg) => async (...a) => { try { const r = await fn(...a); if (msg) toast(msg, 'ok'); return r; } catch (x) { fail(x); } };

