async function loadHolders() { const b = document.getElementById('accBatch'); const box = document.getElementById('holders'); if (!b || !box) return; if (!b.value) { box.innerHTML = ''; return; } try { const l = await api('GET', '/access/batch/' + b.value); box.innerHTML = '<div class="sec">Holders · ' + l.length + '</div>' + (l.length ? l.slice(0, 50).map((s) => '<div class="kv"><span>' + e(s.name) + ' · ' + e(s.userId) + '</span><b><button class="btn sm danger" data-a="acc-rm" data-b="' + e(b.value) + '" data-u="' + e(s.userId) + '"><i class="ti ti-x"></i></button></b></div>').join('') : empty('key', 'No one yet')); } catch (x) { fail(x); } }

